result = detect_objects(frame_ids=[0,8,16], categories=['table'])
if result['status'] == 'fault':
    # 检测服务不可用，直接视觉估计
    return ReturnAnswer(1)
elif result['status'] == 'empty':
    # 有效空检出，没有检测到桌子
    return ReturnAnswer(0)
else:
    # 有检测结果，检查是否检测到桌子
    detections = result['detections']
    table_count = 0
    for detection in detections:
        if detection['category_name'] == 'table':
            table_count += 1
    return ReturnAnswer(table_count)
